   $ex${"titre":"Le tube qui garde sa couleur","competence":"experimenter","situation":"On mélange de l’empois d’amidon avec de la salive, à 37 °C (la température du corps). L’eau iodée devient bleu-noir en présence d’amidon ; sans amidon, elle reste jaune-orangé.","documents":[{"id":"tubes","type":"tableau","titre":"Résultats après 15 minutes","colonnes":["Tube","Contenu","Couleur avec l’eau iodée"],"lignes":[["A","Empois d’amidon + eau","Bleu-noir"],["B","Empois d’amidon + salive","Jaune-orangé"],["C","Empois d’amidon + salive préalablement portée à ébullition","Bleu-noir"]],"enteteLignes":true,"source":"Expérience décrite pour l’exercice"}],"questions":[{"enonce":"Touche la couleur obtenue dans le tube témoin, celui où l’on n’a pas mis de salive.","aide":"Le témoin est le tube où l’on n’ajoute pas la salive.","type":"zone","document":"tubes","multiple":false},{"enonce":"Que prouve le tube B, comparé au témoin ?","aide":"Entre A et B, une seule chose change : la salive.","type":"choix","options":[{"id":"a","texte":"La salive contient de l’amidon"},{"id":"b","texte":"L’eau iodée détruit l’amidon"},{"id":"c","texte":"La salive fait disparaître l’amidon"},{"id":"d","texte":"L’amidon disparaît tout seul en 15 minutes"}],"multiple":false},{"enonce":"Dans le tube C, l’amidon est encore présent. Que peut-on en déduire ?","aide":"Compare C à B : la seule différence est l’ébullition de la salive.","type":"choix","options":[{"id":"a","texte":"La salive portée à ébullition n’agit plus : ses enzymes ne fonctionnent plus"},{"id":"b","texte":"La salive ne joue aucun rôle dans la digestion de l’amidon, qui se conserve seul"},{"id":"c","texte":"L’ébullition a fabriqué de l’amidon à partir des sucres présents dans la salive"},{"id":"d","texte":"La salive bouillie a transformé l’amidon en protéines, ce qui l’a rendu invisible"}],"multiple":false},{"enonce":"Quel est le nom de l’enzyme de la salive qui coupe l’amidon ? (un mot)","aide":"Son nom commence comme celui de l’amidon : « amy- ».","type":"texte"},{"enonce":"Complète la conclusion.","aide":"L’amidon est un glucide complexe.","type":"trous","segments":["L’amylase coupe l’amidon en petites molécules de ",0," ."],"banque":["acides aminés","glycérol","acides gras","glucose"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Le tube A est le témoin : sans salive, l’amidon est intact et l’eau iodée devient **bleu-noir**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Entre A et B, seule la salive change, et l’amidon a disparu : **la salive attaque l’amidon**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Une enzyme est fragile : après ébullition elle n’agit plus, et le tube C reste **bleu-noir** comme le témoin."},{"cle":{"type":"texte","acceptes":["amylase","l amylase"]},"affichage":"amylase","explication":"C’est l’**amylase**."},{"cle":{"type":"trous","trous":[["glucose"]]},"affichage":"glucose","explication":"L’amidon est coupé en **glucose**, assez petit pour traverser la paroi de l’intestin."}]$ex$::jsonb),
