  ('6dfe56f4-af50-5408-8d5a-ec63940d46c0'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La phalène du bouleau","competence":"lire-graphique","situation":"La phalène du bouleau est un papillon de nuit qui se pose sur les troncs. Elle existe en deux formes, claire et sombre. Au XIXe siècle, la suie des usines a noirci les troncs des bouleaux autour de Manchester.","documents":[{"id":"phalene","type":"graphique","forme":"barres","titre":"Part des deux formes dans la population","categories":["1850","1895","1960","1990"],"series":[{"nom":"Forme sombre (%)","valeurs":[2,98,50,5],"teinte":"encre"},{"nom":"Forme claire (%)","valeurs":[98,2,50,95],"teinte":"sable"}],"axeY":{"titre":"Part de la population","unite":"%","min":0,"max":100,"pas":20},"axeX":{"titre":"Année"},"valeurs":false,"source":"Valeurs simplifiées, inspirées des observations de la région de Manchester"}],"questions":[{"enonce":"En 1895, quel est le pourcentage de phalènes de forme sombre ?","aide":"Lis la barre sombre au-dessus de 1895.","type":"nombre","unite":"%"},{"enonce":"Pourquoi les phalènes sombres dominent-elles en 1895 ?","aide":"Les oiseaux repèrent leurs proies à la vue.","type":"choix","options":[{"id":"a","texte":"La suie provoque une mutation qui rend les phalènes sombres, et elle se transmet"},{"id":"b","texte":"Les phalènes claires sont parties vivre ailleurs, là où les troncs sont restés clairs"},{"id":"c","texte":"Les papillons changent de couleur au cours de leur vie pour se cacher des oiseaux"},{"id":"d","texte":"Sur les troncs noircis, elles sont moins repérées et moins mangées par les oiseaux"}],"multiple":false},{"enonce":"Touche l’année où les deux formes sont aussi nombreuses l’une que l’autre.","aide":"Cherche les deux barres de même hauteur.","type":"zone","document":"phalene","multiple":false},{"enonce":"De combien de points la part de phalènes sombres a-t-elle augmenté entre 1850 et 1895 ?","aide":"Soustrais : 98 − 2.","type":"nombre","unite":"points"}]}$ex$::jsonb,
