   $ex${"titre":"Les pinsons de la sécheresse","competence":"analyser-document","situation":"Sur l’île de Daphne (Galápagos), une sécheresse a fait disparaître presque toutes les petites graines. Seuls les pinsons à bec épais savent casser les grosses graines dures.","documents":[{"id":"pinsons","type":"tableau","titre":"Une population de pinsons","colonnes":["Année","Nombre de pinsons","Épaisseur moyenne du bec (mm)"],"lignes":[["1976","1 200","9,2"],["1978, après la sécheresse","180","9,7"]],"enteteLignes":true,"source":"Valeurs arrondies, d’après les travaux de Peter et Rosemary Grant"},{"id":"graines","type":"tableau","titre":"Les graines disponibles","colonnes":["Graines","Avant la sécheresse","Pendant la sécheresse"],"lignes":[["Petites graines molles","Très nombreuses","Presque toutes disparues"],["Grosses graines dures","Rares","Toujours disponibles"]],"enteteLignes":true,"source":"Données simplifiées"}],"questions":[{"enonce":"Quel pourcentage des pinsons a disparu entre 1976 et 1978 ? (arrondi à l’unité)","aide":"Calcule (1 200 − 180) ÷ 1 200.","type":"nombre","unite":"%"},{"enonce":"De combien de millimètres l’épaisseur moyenne du bec a-t-elle augmenté ?","aide":"Soustrais : 9,7 − 9,2.","type":"nombre","unite":"mm"},{"enonce":"Touche la case qui dit ce qui reste disponible pendant la sécheresse pour les grosses graines.","aide":"Lis la ligne « Grosses graines dures ».","type":"zone","document":"graines","multiple":false},{"enonce":"Pourquoi le bec moyen est-il devenu plus épais ?","aide":"Un individu ne décide pas de la forme de son bec.","type":"choix","options":[{"id":"a","texte":"La sécheresse a provoqué des mutations utiles"},{"id":"b","texte":"Les pinsons à bec épais ont mieux survécu et eu plus de descendants"},{"id":"c","texte":"Chaque pinson a épaissi son bec à force de casser des graines dures"},{"id":"d","texte":"Les pinsons à petit bec ont appris à casser les graines dures"}],"multiple":false},{"enonce":"Comment s’appelle ce tri des individus par le milieu ?","aide":"Ici, le milieu trie selon l’avantage : ce n’est pas le pur hasard.","type":"choix","options":[{"id":"a","texte":"La mitose"},{"id":"b","texte":"La dérive génétique"},{"id":"c","texte":"La sélection naturelle"},{"id":"d","texte":"La spéciation"}],"multiple":false}]}$ex$::jsonb,
