   $ex${"titre":"Quand deux plaques se rencontrent","competence":"observer-schema","situation":"Sur ces schémas vus de dessus, deux plaques voisines (en brun) se déplacent. Les flèches montrent le sens de leur mouvement et chaque lettre repère une façon de se rencontrer.","documents":[{"id":"rencontres","type":"schema","titre":"Trois rencontres entre deux plaques (vues de dessus)","largeur":340,"hauteur":215,"elements":[{"forme":"rect","x":50,"y":26,"l":100,"h":24,"teinte":"brun","motif":"clair"},{"forme":"rect","x":190,"y":26,"l":100,"h":24,"teinte":"brun","motif":"clair"},{"forme":"ligne","de":[130,18],"a":[70,18],"teinte":"encre","fleche":"fin"},{"forme":"ligne","de":[210,18],"a":[270,18],"teinte":"encre","fleche":"fin"},{"forme":"rect","x":50,"y":96,"l":100,"h":24,"teinte":"brun","motif":"clair"},{"forme":"rect","x":190,"y":96,"l":100,"h":24,"teinte":"brun","motif":"clair"},{"forme":"ligne","de":[70,88],"a":[130,88],"teinte":"encre","fleche":"fin"},{"forme":"ligne","de":[270,88],"a":[210,88],"teinte":"encre","fleche":"fin"},{"forme":"rect","x":50,"y":166,"l":100,"h":24,"teinte":"brun","motif":"clair"},{"forme":"rect","x":190,"y":166,"l":100,"h":24,"teinte":"brun","motif":"clair"},{"forme":"ligne","de":[100,186],"a":[100,170],"teinte":"encre","fleche":"fin"},{"forme":"ligne","de":[240,170],"a":[240,186],"teinte":"encre","fleche":"fin"},{"forme":"cercle","cx":24,"cy":38,"r":11,"texte":"A","teinte":"encre","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":24,"cy":108,"r":11,"texte":"B","teinte":"encre","motif":"clair","id":"z2","zone":true},{"forme":"cercle","cx":24,"cy":178,"r":11,"texte":"C","teinte":"encre","motif":"clair","id":"z3","zone":true}]}],"questions":[{"enonce":"Touche la lettre du schéma où les deux plaques s’écartent.","aide":"Regarde le sens des flèches : elles partent chacune de leur côté.","type":"zone","document":"rencontres","multiple":false},{"enonce":"Touche la lettre du schéma où les deux plaques glissent l’une contre l’autre.","aide":"Cherche les flèches qui vont dans des sens opposés, mais le long de la frontière.","type":"zone","document":"rencontres","multiple":false},{"enonce":"Associe chaque lettre du schéma au nom de la frontière.","aide":"Divergent : on s’écarte. Convergent : on se rapproche. Coulissant : on glisse.","type":"association","gauche":[{"id":"g0","texte":"A"},{"id":"g1","texte":"B"},{"id":"g2","texte":"C"}],"droite":[{"id":"d0","texte":"Frontière coulissante"},{"id":"d1","texte":"Frontière divergente"},{"id":"d2","texte":"Frontière convergente"}]},{"enonce":"Une plaque avance de 3 cm par an. Quelle distance parcourt-elle en 1 million d’années, en kilomètres ?","aide":"1 million d’années × 3 cm = 3 millions de cm ; 100 000 cm font 1 km.","type":"nombre","unite":"km"}]}$ex$::jsonb,
