  ('b8e3138b-fa4b-5f65-ab81-9eeef42fd6b8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’âge du plancher océanique","competence":"lire-graphique","situation":"Des chercheurs datent les roches du fond de l’océan le long d’une ligne qui part d’une dorsale (0 km) et s’en éloigne. Les âges sont arrondis et imaginés pour l’exercice.","documents":[{"id":"plancher","type":"graphique","forme":"barres","titre":"Âge des roches du fond de l’océan","categories":["0 km","100 km","200 km","300 km","400 km"],"series":[{"nom":"Âge","valeurs":[0,5,10,15,20],"teinte":"turquoise"}],"axeY":{"titre":"Âge des roches","unite":"en millions d’années","min":0,"max":25,"pas":5},"axeX":{"titre":"Distance à la dorsale"}}],"questions":[{"enonce":"Touche la barre qui correspond à des roches de 10 millions d’années.","aide":"Lis l’axe vertical : cherche la graduation 10.","type":"zone","document":"plancher","multiple":false},{"enonce":"Entre la dorsale et le forage situé à 100 km, le plancher s’est éloigné de 100 km en 5 millions d’années. À quelle vitesse, en cm par an ?","aide":"100 km = 10 000 000 cm. Divise par 5 000 000 années.","type":"nombre","unite":"cm/an"},{"enonce":"Un forage est fait à 250 km de la dorsale. Quel âge attend-on pour les roches, en millions d’années ?","aide":"L’âge augmente de la même quantité tous les 100 km : regarde de combien.","type":"nombre","unite":"millions d’ans"},{"enonce":"Que montre ce graphique ?","aide":"Regarde où se trouvent les roches les plus jeunes.","type":"choix","options":[{"id":"a","texte":"Les roches les plus anciennes se trouvent sur la dorsale, là où la lithosphère s’enfonce"},{"id":"b","texte":"L’âge des roches ne dépend pas de la distance à la dorsale, il est à peu près le même partout"},{"id":"c","texte":"Les roches sont d’autant plus anciennes qu’elles sont loin de la dorsale, où la lithosphère naît"},{"id":"d","texte":"Les plaques se rapprochent de la dorsale en vieillissant, puis s’y enfoncent sous le manteau"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"À 200 km de la dorsale, les roches ont **10 millions d’années**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 cm/an","explication":"10 000 000 cm ÷ 5 000 000 ans = **2 cm par an**."},{"cle":{"type":"nombre","valeur":12.5,"tolerance":0},"affichage":"12,5 millions d’ans","explication":"Tous les 100 km, l’âge augmente de 5 millions d’années : à 250 km, **12,5 millions d’années**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Plus on s’éloigne de la dorsale, plus les roches sont **anciennes** : la lithosphère neuve naît à la dorsale puis s’écarte de chaque côté."}]$ex$::jsonb),
