   $ex${"titre":"Des séismes qui descendent","competence":"analyser-document","situation":"Au large d’un pays imaginaire, une plaque océanique plonge sous une plaque continentale. Des sismologues relèvent les foyers de séismes selon leur distance à la fosse (valeurs arrondies, imaginées pour l’exercice).","documents":[{"id":"fosse","type":"schema","titre":"Coupe d’une zone de subduction","largeur":340,"hauteur":200,"elements":[{"forme":"polygone","points":[[20,56],[168,56],[300,150],[284,168],[154,76],[20,76]],"teinte":"turquoise","motif":"clair","id":"z1","zone":true},{"forme":"polygone","points":[[168,56],[322,56],[322,120],[240,107]],"teinte":"brun","motif":"clair","id":"z2","zone":true},{"forme":"polygone","points":[[262,56],[280,30],[298,56]],"teinte":"corail","motif":"plein","id":"z3","zone":true},{"forme":"texte","x":90,"y":46,"texte":"Océan","taille":"petit","ancre":"milieu"},{"forme":"texte","x":240,"y":88,"texte":"Continent","taille":"petit","ancre":"milieu"},{"forme":"texte","x":70,"y":140,"texte":"Manteau","taille":"petit","ancre":"milieu"}]},{"id":"foyers","type":"tableau","titre":"Les foyers de quatre séismes","colonnes":["Séisme","Distance à la fosse (km)","Profondeur du foyer (km)"],"lignes":[["1",50,25],["2",100,50],["3",200,100],["4",300,150]],"enteteLignes":true}],"questions":[{"enonce":"Touche la plaque qui plonge sous l’autre.","aide":"C’est celle qui s’enfonce dans le manteau.","type":"zone","document":"fosse","multiple":false},{"enonce":"Un séisme a son foyer à 250 km de la fosse. À quelle profondeur attend-on ce foyer, en km ?","aide":"Compare les lignes du tableau : la profondeur est toujours la moitié de la distance.","type":"nombre","unite":"km"},{"enonce":"Que montre l’alignement des foyers dans le tableau ?","aide":"Regarde comment la profondeur change quand on s’éloigne de la fosse.","type":"choix","options":[{"id":"a","texte":"Les foyers sont répartis au hasard : aucune organisation n’apparaît dans le tableau"},{"id":"b","texte":"La plaque reste à la surface : tous les foyers sont à la même profondeur faible"},{"id":"c","texte":"Les foyers sont de plus en plus profonds : ils dessinent la plaque qui s’enfonce"},{"id":"d","texte":"Les plaques s’écartent à la fosse : les foyers s’éloignent les uns des autres"}],"multiple":false},{"enonce":"Touche l’endroit où l’on s’attend à un volcan explosif.","aide":"Les volcans des zones de subduction sont sur la plaque qui chevauche.","type":"zone","document":"fosse","multiple":false}]}$ex$::jsonb,
