de":"Suis le trajet : le Soleil chauffe le sol, le sol renvoie de l’infrarouge, les gaz en retiennent une partie.","type":"association","gauche":[{"id":"g0","texte":"A"},{"id":"g1","texte":"B"},{"id":"g2","texte":"C"},{"id":"g3","texte":"D"}],"droite":[{"id":"d0","texte":"Infrarouge qui s’échappe vers l’espace"},{"id":"d1","texte":"Infrarouge renvoyé par le sol"},{"id":"d2","texte":"Rayonnement solaire qui arrive"},{"id":"d3","texte":"Infrarouge renvoyé vers le sol par les gaz"}]},{"enonce":"Touche la lettre de la flèche qui diminue si l’on ajoute des gaz à effet de serre dans l’atmosphère.","aide":"Plus de gaz retient plus d’infrarouge : quelle flèche s’affaiblit ?","type":"zone","document":"serre","multiple":false},{"enonce":"Classe chaque source selon le gaz qu’elle émet.","aide":"Relis la colonne « Sources principales » du tableau.","type":"categories","categories":[{"id":"c0","texte":"Dioxyde de carbone"},{"id":"c1","texte":"Méthane"},{"id":"c2","texte":"Protoxyde d’azote"}],"items":[{"id":"i0","texte":"Une fuite sur un gazoduc"},{"id":"i1","texte":"Une centrale au charbon"},{"id":"i2","texte":"Une rizière inondée"},{"id":"i3","texte":"Un engrais épandu sur un champ"},{"id":"i4","texte":"La fabrication du ciment"}]},{"enonce":"Sans aucun effet de serre naturel, que se passerait-il ?","aide":"Sans gaz pour retenir l’infrarouge, toute la chaleur s’échapperait.","type":"choix","options":[{"id":"a","texte":"Il n’y aurait plus de lumière du Soleil qui atteigne la Terre"},{"id":"b","texte":"La Terre serait beaucoup plus chaude, donc aussi inhabitable"},{"id":"c","texte":"Rien ne changerait sur la température moyenne de la planète"},{"id":"d","texte":"La Terre serait beaucoup plus froide, sans doute inhabitable"}],"multiple":false}]}$ex$::jsonb,
